contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint w) public payable {
        require(v != w);

        bool setReverted;
        c.SetMinSum(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setReverted = true; } else { setReverted = false; }

        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { initReverted = true; } else { initReverted = false; }

        bool laterSetReverted;
        c.SetMinSum(w); bool __rev2 = __ESBMC_reverted(); if (__rev2) { laterSetReverted = true; } else { laterSetReverted = false; }

        assert(!setReverted && !initReverted && laterSetReverted && c.MinSum() == v);
    }

    receive() external payable {}
}

