pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v, uint256 w) internal {
        vm.assume(v != w);
        bool setReverted;
        try c.SetMinSum(v) { setReverted = false; } catch { setReverted = true; }
        bool initReverted;
        try c.Initialized() { initReverted = false; } catch { initReverted = true; }
        bool laterSetReverted;
        try c.SetMinSum(w) { laterSetReverted = false; } catch { laterSetReverted = true; }
        assertTrue(!setReverted && !initReverted && laterSetReverted && c.MinSum() == v);
    }

    function testFuzz_run(uint256 v, uint256 w) public {
        _run(v, w);
    }

    receive() external payable {}
}
